package cli

import (
	"fmt"
	"os"
	"path/filepath"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func doctorCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "doctor [feature]",
		Short: "Run health checks on workspaces",
		Long: `Check workspace and stack health. With no args, checks all features.

Also reports stack ancestry for every configured parent-child edge: current,
stale, divergent, missing, cross-repo-unsupported, or unevaluated, each with its
reason and actionable guidance when available. Ancestry evaluation is strictly
read-only and never contacts a remote; when the source repository cannot be
determined the feature reports a single informational line and the remaining
checks still run.

Warnings such as a dirty checkout, active Git operation, stale ancestry, or
recoverable lock/session state are reported with exit 0 for interactive use.
Corrupt or unreadable persisted state returns a non-zero exit status.`,
		Args: cobra.MaximumNArgs(1),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			if len(args) == 0 {
				return internal.ListFeatures(), cobra.ShellCompDirectiveNoFileComp
			}
			return nil, cobra.ShellCompDirectiveNoFileComp
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			// Checkout mode dispatch
			ws, wsErr := internal.RequireWorkspace()
			if wsErr != nil {
				// Fail closed on persisted-state errors. A workspace that
				// cannot be resolved from inside a Git repository means the
				// repo-local config is unusable (invalid workspace_mode, for
				// example) and doctor must report it instead of silently
				// continuing in external mode. Only a cwd with no repository
				// at all — an external workspace root or feature directory —
				// may fall through, which is the case ancestry then reports as
				// unevaluated.
				if _, repoErr := internal.MainRepoRoot(); repoErr == nil {
					return wsErr
				}
			} else if ws.Mode == internal.ModeCheckout {
				feature := ""
				if len(args) == 1 {
					feature = args[0]
				}
				return runCheckoutDoctor(ws, feature)
			}

			cfg := internal.LoadConfig()

			if len(args) == 1 {
				_, err := checkFeatureE(ws, cfg, args[0])
				return err
			}

			// Check all features
			features, listErr := internal.ListFeaturesE()
			if listErr != nil {
				return listErr
			}
			if len(features) == 0 {
				fmt.Println("No features found.")
				return nil
			}

			totalIssues := 0
			for _, feature := range features {
				issues, err := checkFeatureE(ws, cfg, feature)
				if err != nil {
					return err
				}
				totalIssues += issues
			}

			if totalIssues == 0 {
				fmt.Println("\nAll healthy.")
			} else {
				fmt.Printf("\n%d issue(s) found.\n", totalIssues)
			}
			return nil
		},
	}
}

func checkFeatureE(ws internal.Workspace, cfg internal.Config, feature string) (int, error) {
	// Resolve from the workspace the command already resolved rather than
	// re-deriving one: doctor must still run from an external workspace root
	// or feature directory when the source repository is unavailable, which is
	// exactly the case ancestry then reports as unevaluated.
	featurePath, err := internal.ResolveFeaturePathFor(ws, feature)
	if err != nil {
		return 0, err
	}

	if _, err := os.Stat(featurePath); os.IsNotExist(err) {
		fmt.Printf("%s: not found\n", feature)
		return 0, nil
	}

	issues := internal.CheckFeatureHealth(featurePath)

	if stack, sErr := internal.LoadStack(featurePath); sErr == nil && len(stack.Branches) > 0 {
		edges, res := internal.FeatureStackEdges(ws, cfg, feature, featurePath, stack)
		issues = append(issues, internal.AncestryHealthIssues(res, edges)...)
	}

	counted := internal.CountHealthIssues(issues)

	if counted == 0 {
		// Count active worktrees
		wtDir := filepath.Join(featurePath, "worktrees")
		entries, _ := os.ReadDir(wtDir)
		active := 0
		for _, e := range entries {
			if e.IsDir() {
				active++
			}
		}
		fmt.Printf("%s: healthy (%d active worktree(s))\n", feature, active)
	} else {
		fmt.Printf("%s: %d issue(s)\n", feature, counted)
	}
	for _, issue := range issues {
		fmt.Println(issue)
	}

	return counted, nil
}

func runCheckoutDoctor(ws internal.Workspace, feature string) error {
	report, err := internal.BuildCheckoutHealthReport(ws, nil)
	if err != nil {
		return err
	}
	if feature != "" {
		if err := report.FilterFeature(feature); err != nil {
			return err
		}
	}
	fmt.Print(internal.FormatCheckoutHealth(report))
	if report.HasErrors() {
		return fmt.Errorf("checkout workspace has corrupt or unreadable state")
	}
	return nil
}

package cli

import (
	"bytes"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
)

// doctorFeatureContext resolves the workspace and config the way doctorCmd
// does, so tests exercise checkFeatureE exactly as the command does.
func doctorFeatureContext(t *testing.T) (internal.Workspace, internal.Config) {
	t.Helper()
	cfg := internal.LoadConfig()
	ws, err := internal.RequireWorkspace()
	if err != nil {
		return internal.Workspace{}, cfg
	}
	return ws, cfg
}

// withSiblingWorkspaceEnv points TWS_ROOT at the sibling metadata root that
// RequireWorkspace derives for an external repository, so the feature paths
// used by createWorktree and by RequireFeaturePath agree.
func withSiblingWorkspaceEnv(t *testing.T, repo string) {
	t.Helper()
	t.Setenv("HOME", t.TempDir())
	canonical := repo
	if resolved, err := filepath.EvalSymlinks(repo); err == nil {
		canonical = filepath.Clean(resolved)
	}
	t.Setenv("TWS_ROOT", canonical+".tws")
	oldCWD, _ := os.Getwd()
	t.Cleanup(func() { _ = os.Chdir(oldCWD) })
	if err := os.Chdir(repo); err != nil {
		t.Fatal(err)
	}
}

func externalGit(t *testing.T, dir string, args ...string) string {
	t.Helper()
	cmd := exec.Command("git", args...)
	cmd.Dir = dir
	out, err := cmd.CombinedOutput()
	if err != nil {
		t.Fatalf("git %v: %v\n%s", args, err, out)
	}
	return strings.TrimSpace(string(out))
}

// canonicalMainRoot mirrors the evaluator's candidate normalisation.
func canonicalMainRoot(t *testing.T, path string) string {
	t.Helper()
	root, err := internal.MainRepoRootIn(path)
	if err != nil {
		t.Fatalf("MainRepoRootIn(%q): %v", path, err)
	}
	if resolved, rErr := filepath.EvalSymlinks(root); rErr == nil {
		return filepath.Clean(resolved)
	}
	abs, _ := filepath.Abs(root)
	return filepath.Clean(abs)
}

func countAncestryWarnings(issues []internal.HealthIssue) int {
	n := 0
	for _, issue := range issues {
		if issue.EffectiveSeverity() == internal.SeverityWarning {
			n++
		}
	}
	return n
}

// ---------- AC 31: external doctor reports ancestry ----------

func TestExternalDoctor_AncestryReported(t *testing.T) {
	repo := setupGitRepo(t, "main")
	withSiblingWorkspaceEnv(t, repo)

	if err := createWorktree("extfeat", "branch1", "main", "", false); err != nil {
		t.Fatalf("createWorktree: %v", err)
	}
	// Advance the parent behind the child's back.
	externalGit(t, repo, "commit", "--allow-empty", "-m", "advance main")

	ws, cfg := doctorFeatureContext(t)
	featurePath, err := internal.RequireFeaturePath("extfeat")
	if err != nil {
		t.Fatal(err)
	}
	stack, err := internal.LoadStack(featurePath)
	if err != nil {
		t.Fatal(err)
	}
	edges, res := internal.FeatureStackEdges(ws, cfg, "extfeat", featurePath, stack)
	if res.RepoDir == "" {
		t.Fatalf("expected a resolved repository, got %+v", res)
	}
	issues := internal.AncestryHealthIssues(res, edges)
	found := false
	for _, issue := range issues {
		if issue.Branch == "branch1" && strings.Contains(issue.Problem, "ancestry stale") {
			found = true
		}
	}
	if !found {
		t.Fatalf("expected a stale ancestry issue naming branch1, got %+v (edges %+v)", issues, edges)
	}

	var counted int
	out := captureStdout(t, func() {
		counted, err = checkFeatureE(ws, cfg, "extfeat")
	})
	if err != nil {
		t.Fatalf("checkFeatureE: %v", err)
	}
	if counted != countAncestryWarnings(issues) {
		t.Errorf("printed total %d, want %d", counted, countAncestryWarnings(issues))
	}
	if !strings.Contains(out, "ancestry stale") {
		t.Errorf("expected the ancestry issue in output:\n%s", out)
	}
}

// ---------- AC 32: repository unavailable fails soft ----------

func TestExternalDoctor_RepoUnavailable(t *testing.T) {
	repo := setupGitRepo(t, "main")
	withSiblingWorkspaceEnv(t, repo)

	// An external workspace with no materialized worktree and no inferable
	// source repository. It is deliberately not a `<repo>.tws` sibling, so
	// nothing can infer a repository back from its path.
	isolated := filepath.Join(t.TempDir(), "detached-workspace")
	featurePath := filepath.Join(isolated, "orphanfeat")
	if err := os.MkdirAll(featurePath, 0755); err != nil {
		t.Fatal(err)
	}
	if err := internal.EnsureExternalWorkspaceMarker(isolated); err != nil {
		t.Fatal(err)
	}
	stack := internal.Stack{Branches: []internal.StackEntry{
		{Name: "a", Base: "main"},
		{Name: "b", Base: "a"},
		{Name: "c", Base: "b"},
	}}
	if err := internal.SaveStack(featurePath, stack); err != nil {
		t.Fatal(err)
	}

	ws := internal.Workspace{MetadataRoot: isolated, Mode: internal.ModeExternal}

	probe := internal.ResolveStackAncestryRepo(ws, internal.Config{}, featurePath, stack)
	if probe.RepoDir != "" {
		t.Fatalf("expected an unresolvable repository, got %+v", probe)
	}
	edges, res := internal.FeatureStackEdges(ws, internal.Config{}, "orphanfeat", featurePath, stack)
	issues := internal.AncestryHealthIssues(res, edges)

	if len(issues) != 1 {
		t.Fatalf("expected exactly one collapsed issue regardless of entry count, got %+v", issues)
	}
	if issues[0].Branch != "stack" || issues[0].EffectiveSeverity() != internal.SeverityInfo {
		t.Errorf("unexpected issue: %+v", issues[0])
	}
	if internal.CountHealthIssues(issues) != 0 {
		t.Error("an informational issue must not change the total")
	}

	var counted int
	var err error
	out := captureStdout(t, func() {
		counted, err = checkFeatureE(ws, internal.Config{}, "orphanfeat")
	})
	if err != nil {
		t.Fatalf("checkFeatureE: %v", err)
	}
	if counted != 0 {
		t.Errorf("counted = %d, want the pre-feature total of 0", counted)
	}
	if !strings.Contains(out, "healthy (") {
		t.Errorf("the healthy line must still be printed:\n%s", out)
	}
	if !strings.Contains(out, "repo-unavailable") {
		t.Errorf("the info issue must still be printed:\n%s", out)
	}

	// The non-Git health checks still run and still report when broken.
	if err := createWorktree("brokenfeat", "branch1", "main", "", false); err != nil {
		t.Fatalf("createWorktree: %v", err)
	}
	wt := internal.WorktreePath("brokenfeat", "branch1")
	externalGit(t, wt, "checkout", "-b", "unexpected")
	brokenIssues := internal.CheckFeatureHealth(internal.FeaturePath("brokenfeat"))
	if internal.CountHealthIssues(brokenIssues) == 0 {
		t.Error("worktree branch mismatch must still be reported")
	}
}

