func TestStackAncestry_ProcessBound(t *testing.T) {
	shim := withGitShim(t)
	dir, _ := setupHealthTestRepo(t)
	forkChild(t, dir, "shared", "main", 1)
	for _, name := range []string{"c1", "c2", "c3", "c4"} {
